private func hash(_ i: Int, _ s: Double) -> Double { let v = sin(Double(i) * s) * 43758.5453; return v - v.rounded(.down) }

struct AuraBackground: View {
    var energy: Double = 0.6
    @State private var t: Double = 0.0
    private let timer = Timer.publish(every: 1.0 / 30.0, on: .main, in: .common).autoconnect()
    var body: some View {
        let e = max(0.0, min(2.0, energy))
        return Canvas { ctx, size in drawScene(ctx, size, t, e) }
            .ignoresSafeArea()
            .onReceive(timer) { _ in t += 1.0 / 30.0 }
    }
}
private func drawScene(_ ctx: GraphicsContext, _ size: CGSize, _ t: Double, _ e: Double) {
    let W = Double(size.width), H = Double(size.height)
    ctx.fill(Path(CGRect(origin: .zero, size: size)), with: .color(Color(red: 0.011, green: 0.011, blue: 0.02)))
    drawStars(ctx, size, t)
    drawWorldMap(ctx, size, t)
    drawComet(ctx, size, t)
    let vig = GraphicsContext.Shading.radialGradient(
        Gradient(colors: [.clear, .black.opacity(0.2)]),
        center: CGPoint(x: W / 2, y: H / 2), startRadius: min(W, H) * 0.55, endRadius: max(W, H))
    ctx.fill(Path(CGRect(origin: .zero, size: size)), with: vig)
}
private func drawWorldMap(_ ctx: GraphicsContext, _ size: CGSize, _ t: Double) {
    let W = Double(size.width), H = Double(size.height)
    let cols = Double(WorldMap.cols), rows = Double(WorldMap.nrows)
    let mapH = H * 0.9, offY = H * 0.05
    let stepX = W / cols, stepY = mapH / rows
    let g = WorldMap.grid
    let mcx = W / 2, mcy = offY + mapH / 2
    let aspect = mapH / W
    let period = 42.0
    let swA = (t / period - (t / period).rounded(.down)) * 2 * Double.pi
    let trail = 0.26
    for r in 0..<WorldMap.nrows {
        let rowArr = g[r]
        for c in 0..<WorldMap.cols {
            if rowArr[c] != "1" { continue }
            let x = Double(c) * stepX + stepX / 2
            let y = offY + Double(r) * stepY + stepY / 2
            let a = atan2((y - mcy) / aspect, x - mcx)
            var delta = swA - a
            delta = delta - (delta / (2 * Double.pi)).rounded(.down) * 2 * Double.pi
            let near = delta < trail ? (1 - delta / trail) : 0
            let baseHue = 0.04 + 0.5 * (Double(c) / cols)
            let hue = baseHue + (0.085 - baseHue) * (near * 0.9)
            let bright = 0.5 + 0.45 * near
            let sat = 0.72 + 0.22 * near
            let sz = 1.3 + 1.3 * near
            ctx.fill(Path(ellipseIn: CGRect(x: x - sz / 2, y: y - sz / 2, width: sz, height: sz)),
                     with: .color(Color(hue: hue, saturation: sat, brightness: bright, opacity: 0.66 + 0.32 * near)))
        }
    }
    let reach = max(W, mapH)
    var wedge = Path(); wedge.move(to: CGPoint(x: mcx, y: mcy))
    for i in 0...24 {
        let aa = swA - trail * Double(i) / 24.0
        wedge.addLine(to: CGPoint(x: mcx + cos(aa) * reach, y: mcy + sin(aa) * reach * aspect))
    }
    wedge.closeSubpath()
    ctx.fill(wedge, with: .color(Color(red: 1, green: 0.69, blue: 0.28).opacity(0.07)))
    var beam = Path(); beam.move(to: CGPoint(x: mcx, y: mcy))
    beam.addLine(to: CGPoint(x: mcx + cos(swA) * reach, y: mcy + sin(swA) * reach * aspect))
    ctx.stroke(beam, with: .color(Color(red: 1, green: 0.82, blue: 0.42).opacity(0.42)), lineWidth: 1.6)
    let cities: [(Double, Double)] = [(40.7, -74), (51.5, -0.1), (35.7, 139.7), (-33.9, 151.2), (37.8, -122.4), (25.2, 55.3), (-23.5, -46.6), (1.3, 103.8)]
    for (i, ct) in cities.enumerated() {
        let x = (ct.1 + 180) / 360 * W
        let y = offY + (90 - ct.0) / 180 * mapH
        let ph = 0.5 + 0.5 * sin(t * 1.2 + Double(i) * 1.1)
        let s = 2.4 + 2.6 * ph
        ctx.fill(Path(ellipseIn: CGRect(x: x - s, y: y - s, width: s * 2, height: s * 2)), with: .color(BG_HOT.opacity(0.3 + 0.4 * ph)))
    }
}
private func drawStars(_ ctx: GraphicsContext, _ size: CGSize, _ t: Double) {
    let W = Double(size.width), H = Double(size.height)
    for i in 0..<60 {
        let x = hash(i, 12.9898) * W
        let y = hash(i, 78.233) * H
        let twin = 0.5 + 0.5 * sin(t * (0.3 + hash(i, 1.7) * 1.0) + Double(i))
        let op = (0.05 + 0.12 * hash(i, 3.17)) * (0.4 + 0.6 * twin)
        let s = 0.6 + 0.9 * hash(i, 5.1)
        ctx.fill(Path(ellipseIn: CGRect(x: x - s / 2, y: y - s / 2, width: s, height: s)), with: .color(.white.opacity(op)))
    }
}
private func drawComet(_ ctx: GraphicsContext, _ size: CGSize, _ t: Double) {
    let W = Double(size.width), H = Double(size.height)
    let period = 18.0
    let cyc = (t / period).rounded(.down)
    let local = t - cyc * period
    let dur = 2.6
    if local >= dur { return }
    let ci = Int(cyc); let p = local / dur
    let start = CGPoint(x: (0.08 + 0.8 * hash(ci, 24.3)) * W, y: (0.04 + 0.2 * hash(ci, 51.7)) * H)
    let ang = Double.pi * 0.16 + hash(ci, 9.1) * 0.34
    let dist = max(W, H) * 0.6
    let fade = sin(p * Double.pi)
    for k in 0..<16 {
        let tpp = max(p - Double(k) / 16 * 0.12, 0)
        let tx = start.x + CGFloat(cos(ang) * dist * tpp)
        let ty = start.y + CGFloat(sin(ang) * dist * tpp)
        let op = fade * (1 - Double(k) / 16) * 0.4
        let s = 1.8 * (1 - Double(k) / 16) + 0.4
        ctx.fill(Path(ellipseIn: CGRect(x: tx - s / 2, y: ty - s / 2, width: s, height: s)), with: .color(BG_HOT.opacity(op)))
    }
}
